'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isEqualDataType = require( '@stdlib/ndarray/base/assert/is-equal-data-type' );
var Float32Array = require( '@stdlib/array/float32' );
var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
var getData = require( '@stdlib/ndarray/data-buffer' );
var getDType = require( '@stdlib/ndarray/dtype' );
var getStrides = require( '@stdlib/ndarray/strides' );
var getOffset = require( '@stdlib/ndarray/offset' );
var getShape = require( '@stdlib/ndarray/shape' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var slogspace = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( slogspace instanceof Error )
};


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Float32Array} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float32', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof slogspace, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function fills a one-dimensional ndarray (endpoint=true)', opts, function test( t ) {
	var endpoint;
	var actual;
	var strt;
	var base;
	var stp;
	var x;

	x = ndarray( 'float32', new Float32Array( [ 0.0, 0.0, 0.0, 0.0 ] ), [ 4 ], [ 1 ], 0, 'row-major' );
	base = scalar2ndarray( 10.0, {
		'dtype': 'float32'
	});
	strt = scalar2ndarray( 0.0, {
		'dtype': 'float32'
	});
	stp = scalar2ndarray( 3.0, {
		'dtype': 'float32'
	});
	endpoint = scalar2ndarray( true, {
		'dtype': 'bool'
	});

	actual = slogspace( [ x, base, strt, stp, endpoint ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.strictEqual( isEqualDataType( getDType( actual ), 'float32' ), true, 'returns expected value' );
	t.deepEqual( getData( actual ), new Float32Array( [ 1.0, 10.0, 100.0, 1000.0 ] ), 'returns expected value' );
	t.deepEqual( getShape( actual ), [ 4 ], 'returns expected value' );
	t.deepEqual( getStrides( actual ), [ 1 ], 'returns expected value' );
	t.strictEqual( getOffset( actual ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function fills a one-dimensional ndarray (endpoint=false)', opts, function test( t ) {
	var endpoint;
	var actual;
	var strt;
	var base;
	var stp;
	var x;

	x = ndarray( 'float32', new Float32Array( [ 0.0, 0.0 ] ), [ 2 ], [ 1 ], 0, 'row-major' );
	base = scalar2ndarray( 2.0, {
		'dtype': 'float32'
	});
	strt = scalar2ndarray( 1.0, {
		'dtype': 'float32'
	});
	stp = scalar2ndarray( 3.0, {
		'dtype': 'float32'
	});
	endpoint = scalar2ndarray( false, {
		'dtype': 'bool'
	});

	actual = slogspace( [ x, base, strt, stp, endpoint ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.strictEqual( isEqualDataType( getDType( actual ), 'float32' ), true, 'returns expected value' );
	t.deepEqual( getData( actual ), new Float32Array( [ 2.0, 4.0 ] ), 'returns expected value' );
	t.deepEqual( getShape( actual ), [ 2 ], 'returns expected value' );
	t.deepEqual( getStrides( actual ), [ 1 ], 'returns expected value' );
	t.strictEqual( getOffset( actual ), 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an input ndarray having a non-unit stride', opts, function test( t ) {
	var expected;
	var endpoint;
	var actual;
	var base;
	var strt;
	var xbuf;
	var stp;
	var x;

	xbuf = new Float32Array( [ 0.0, -1.0, 0.0, -1.0, 0.0 ] );
	x = vector( xbuf, 3, 2, 0 );
	base = scalar2ndarray( 2.0, {
		'dtype': 'float32'
	});
	strt = scalar2ndarray( 0.0, {
		'dtype': 'float32'
	});
	stp = scalar2ndarray( 2.0, {
		'dtype': 'float32'
	});
	endpoint = scalar2ndarray( true, {
		'dtype': 'bool'
	});

	actual = slogspace( [ x, base, strt, stp, endpoint ] );

	expected = new Float32Array( [ 1.0, -1.0, 2.0, -1.0, 4.0 ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.deepEqual( getData( actual ), expected, 'returns expected value' );
	t.end();
});

