tape( 'the function supports a float64 base ndarray', opts, function test( t ) {
	var endpoint;
	var actual;
	var base;
	var strt;
	var stp;
	var x;

	x = vector( new Float32Array( [ 0.0, 0.0, 0.0 ] ), 3, 1, 0 );
	base = scalar2ndarray( 10.0, {
		'dtype': 'float64'
	});
	strt = scalar2ndarray( 0.0, {
		'dtype': 'float32'
	});
	stp = scalar2ndarray( 2.0, {
		'dtype': 'float32'
	});
	endpoint = scalar2ndarray( true, {
		'dtype': 'bool'
	});

	actual = slogspace( [ x, base, strt, stp, endpoint ] );
	t.strictEqual( actual, x, 'returns expected value' );
	t.deepEqual( getData( actual ), new Float32Array( [ 1.0, 10.0, 100.0 ] ), 'returns expected value' );
	t.end();
});
